int main(){std::vector<int16_t> sample(32000);for(unsigned n=0;n<sample.size();++n)sample[n]=int16_t(16000*sinf(6.2831853f*220*n/32000));WavView wav{reinterpret_cast<const uint8_t*>(sample.data()),32000,32000,1,16,1,nullptr};GranularState s;s.values[7]=1;s.values[8]=.005f;s.values[9]=0;GranularVoice voice;voice.init(48000);
 for(unsigned octave=0;octave<2;++octave){assert(voice.trigger(wav,57,1,s.values,42));double energy=0,re=0,im=0,other_re=0,other_im=0;for(unsigned n=0;n<96000;++n){float l,r;voice.next(220*float(1u<<octave),true,l,r);assert(__builtin_isfinite(l)&&fabsf(l)<4);if(n>=48000){energy+=l*l;float phase=6.2831853f*220*float(1u<<octave)*n/48000;re+=l*cosf(phase);im+=l*sinf(phase);float other=6.2831853f*220*float(1u<<(1-octave))*n/48000;other_re+=l*cosf(other);other_im+=l*sinf(other);}}assert(energy>.01 && re*re+im*im>100*(other_re*other_re+other_im*other_im));for(unsigned n=0;n<12000;++n){float l,r;voice.next(220,false,l,r);}assert(!voice.active());}
 s.values[1]=s.values[2]=s.values[3]=s.values[9]=s.values[10]=1;assert(voice.trigger(wav,57,1,s.values,7));for(unsigned n=0;n<48000;++n){float l,r;voice.next(440,true,l,r);assert(__builtin_isfinite(l)&&__builtin_isfinite(r));}s=GranularState{};s.values[8]=.005f;
 auto p=std::make_unique<ProjectState>();make_empty_project(*p);p->tracks[0].instrument=Instrument::Granular;p->assets[0].metadata.root=57;p->tracks[0].granular=s;auto e=std::make_unique<Engine>();WavView views[kSampleAssets]{};views[0]=wav;assert(e->stage_project(*p,views));float audio[256]{};e->render(audio,0);for(unsigned n=0;n<4;++n){Command note{CommandType::MidiInput,0,uint8_t(57+n*3),0x90};note.scalar=100;assert(e->submit(note));}e->render(audio,128);assert(e->poly_note_count(0)==4);double routed_energy=0;for(unsigned n=0;n<512;++n){e->render(audio,128);for(float x:audio){assert(__builtin_isfinite(x));routed_energy+=x*x;}}assert(routed_energy>.001);Command fifth{CommandType::MidiInput,0,72,0x90};fifth.scalar=100;assert(e->submit(fifth));e->render(audio,128);assert(e->poly_note_count(0)==4&&e->poly_owner_masks_valid());
 auto ui=std::make_unique<Performance>(*e,*p);assert(ui->assign_sample(0,wav));e->render(audio,0);ui->poll();assert(p->tracks[0].instrument==Instrument::Granular);ui->set_mode(UiMode::Synth);assert(ui->soft_key(2));assert(ui->knob_parameter(2)==engine_target(Instrument::Granular,5));assert(instrument_voice_limit(Instrument::Granular)==4);
 char dir[]="build/granular-XXXXXX";assert(mkdtemp(dir)&&chdir(dir)==0);DesktopFiles fs;DesktopSampleAssets library;library.files(&fs);SessionFiles files(fs,library,*e,*p,*ui);assert(fs.directory("SAMPLES"));uint8_t header[44];assert(wav_header_ch(header,32000,32000,1));assert(fs.write("SAMPLES/Source.wav",0,header,44,true)&&fs.write("SAMPLES/Source.wav",44,sample.data(),sample.size()*2,false));copy_text(p->assets[0].path,96,"SAMPLES/Source.wav");assert(file_checksum(fs,"SAMPLES/Source.wav",p->assets[0].metadata.content_crc));assert(files.save_preset("Grain.mgxp"));auto out=std::make_unique<ProjectState>();assert(read_project_file(fs,"Grain.mgxp",*out));assert(out->tracks[0].instrument==Instrument::Granular && out->tracks[0].granular.values[9]==s.values[9]);assert(files.load_preset("Grain.mgxp"));e->render(audio,0);ui->poll();assert(p->tracks[0].instrument==Instrument::Granular);assert(fs.remove("SAMPLES/Source.wav"));assert(!files.load_preset("Grain.mgxp"));assert(p->tracks[0].instrument==Instrument::Granular);puts("Granular: octave pitch, finite release/routed audio, 4-voice resource/steal, sample assignment/envelope, portable preset mount and missing-asset atomic hold passed");}
